// Offline checks: no model, database or browser fixture is generated by this suite.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const require=createRequire(path.join(root,'package.json')),ts=require('typescript');
async function load(file,imports={}){
 const code=ts.transpileModule(await fs.readFile(path.join(root,file),'utf8'),{fileName:file,compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;
 const loaded={exports:{}};new Function('require','module','exports',code)(name=>{if(Object.hasOwn(imports,name))return imports[name];throw Error('Unexpected import '+name);},loaded,loaded.exports);return loaded.exports;
}
const helper=await load('src/lib/estudio/comparison.ts');
const initial={id:'initial-v1-assistant',role:'assistant',text:'Original independent analysis - offline fixture',citations:[{page:64,printed:58,label:'Known page',href:'/api/biblioteca/BIB-002#page=64'}],createdAt:'2026-10-16T10:00:00.000Z'};
const follow={...initial,id:'followup-assistant',text:'Different coached follow-up - offline fixture'};
test('select original analysis, never latest follow-up',()=>{assert.equal(helper.initialLiterature([initial,follow]),initial);assert.equal(helper.initialLiterature([follow,initial]),initial);});
test('missing initial does not fall back to another response',()=>assert.equal(helper.initialLiterature([follow]),null));
test('empty, user-role and duplicate initial fail closed',()=>{for(const data of [[],[{...initial,text:' '}],[{...initial,role:'user'}],[initial,{...initial}]])assert.equal(helper.initialLiterature(data),null);});
test('selection is pure, does not alter histories or grading',()=>{const messages=[initial,follow],before=JSON.stringify(messages);helper.initialLiterature(messages);assert.equal(JSON.stringify(messages),before);assert(!('selected_answer' in helper.initialLiterature(messages)));});
const React=require('react'),{renderToStaticMarkup}=require('react-dom/server');
const css=new Proxy({},{get:(_target,key)=>key==='__esModule'?false:String(key)});
const component=await load('src/components/estudio/comparison-panel.tsx',{
 'react/jsx-runtime':require('react/jsx-runtime'),
 'next/dynamic':()=>({text})=>React.createElement('div',{'data-offline-renderer':'true'},text),
 '@/lib/estudio/comparison':helper,'@/components/acceso/styles.module.css':css,'./styles.module.css':css,
});
const props={literature:{messages:[initial,follow],loading:false,sending:false,error:''},opinion:{analysis:{text:'Saved independent second opinion - offline fixture',references:[{id:'S1',label:'Controlled source',href:'https://example.invalid/controlled'}]},loading:false,error:'',enabled:true,covered:true},answered:true,focused:false,disabled:false,onExpand:()=>{},onView:()=>{},onVerdict:()=>{}};
const render=patch=>renderToStaticMarkup(React.createElement(component.ComparisonPanel,{...props,...patch}));
test('render exact original texts and provenance, not a synthesized conclusion',()=>{const html=render();assert(html.includes(initial.text));assert(html.includes(props.opinion.analysis.text));assert(!html.includes(follow.text));assert(html.includes('Sin resumen nuevo ni veredicto automático.'));assert.equal((html.match(/data-tutor-response="true"/g)??[]).length,2);assert(html.includes('Análisis guardado del piloto'));});

test('shared editorial base is not mislabeled as Gemini in comparison',()=>{const html=render({literature:{...props.literature,messages:[{...initial,origin:'shared-reviewed'}]}});assert(html.includes('<h4>Literatura · base revisada</h4>'));assert(!html.includes('Literatura · Gemini'));assert(html.includes('lectura compartida, sin nueva consulta'));assert(render().includes('<h4>Literatura · Gemini</h4>'));});
test('no saved answer: hide both analyses even if stale data is supplied',()=>{const html=render({answered:false});assert(!html.includes(initial.text));assert(!html.includes(props.opinion.analysis.text));assert(html.includes('Guarda tu respuesta inicial'));});
test('narrow view uses collapsed readers; focused view opens both',()=>{assert(!render().includes('<details open=""'));assert.equal((render({focused:true}).match(/<details open=""/g)??[]).length,2);});
test('missing providers are honest, not replaced with samples',()=>{const html=render({literature:{messages:[],loading:false,sending:false,error:''},opinion:{analysis:null,loading:false,error:'',enabled:true,covered:false}});assert(html.includes('No hay un análisis inicial'));assert(html.includes('No hay segunda opinión habilitada'));assert(!html.includes('data-tutor-response'));});
test('loading and error states remain visible',()=>{assert(render({opinion:{analysis:null,loading:true,error:''}}).includes('Abriendo el análisis guardado'));assert(render({opinion:{analysis:null,loading:false,error:'Existing error'}}).includes('Existing error'));});
test('both source sets remain controlled links, no new page numbers invented',()=>{const html=render();assert(html.includes(initial.citations[0].href));assert(html.includes(props.opinion.analysis.references[0].href));assert(html.includes('rel="noopener noreferrer"'));});
function elements(node){if(!node||typeof node!=='object')return [];return [node,...React.Children.toArray(node.props?.children).flatMap(elements)];}
test('verdict and expand actions only invoke their navigation callbacks',()=>{let verdict=0,expand=0;const tree=component.ComparisonPanel({...props,onVerdict:()=>verdict++,onExpand:()=>expand++});const nodes=elements(tree);nodes.find(n=>n.type==='button'&&n.props.children==='Ir a mi veredicto').props.onClick();nodes.find(n=>n.type==='button'&&n.props.children==='Leer lado a lado').props.onClick();assert.equal(verdict,1);assert.equal(expand,1);});
test('busy verdict action is disabled',()=>assert(render({disabled:true}).includes('disabled=""')));
test('comparison has no provider API or write path',async()=>{const source=await fs.readFile(path.join(root,'src/components/estudio/comparison-panel.tsx'),'utf8');for(const forbidden of ['fetch(','literature.send(','onChange(','personal_verdict:'])assert(!source.includes(forbidden));const workspace=await fs.readFile(path.join(root,'src/components/estudio/workspace.tsx'),'utf8');assert(workspace.includes('tutorView === "segunda" || tutorView === "comparar"'));assert(workspace.includes('id="personal-verdict"'));});
test('responsive comparison grid is container-sized, mobile remains stacked',async()=>{const css=await fs.readFile(path.join(root,'src/components/estudio/styles.module.css'),'utf8');assert(css.includes('container-name:comparison'));assert(css.includes('@container comparison (min-width:800px)'));assert(css.includes('grid-template-columns:repeat(2,minmax(0,1fr))'));});
